 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find full-width/full-height separator lines (the separator color may vary).
    rs = [r for r, row in enumerate(grid) if len(set(row)) == 1 and row[0] != 0]
    cs = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != 0]
    rb, cb = [-1] + rs + [h], [-1] + cs + [w]
    out = []
    for ri in range(len(rb)-1):
        row = []
        for ci in range(len(cb)-1):
            n = sum(grid[r][c] == 5
                    for r in range(rb[ri]+1, rb[ri+1])
                    for c in range(cb[ci]+1, cb[ci+1]))
            row.append(1 if n == 2 else 3)
        out.append(row)
    return out
